pelanggan.\\\\\'\',\\\\\'\'Minimal SMA, komunikatif\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'5000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-01\\\\\'\',\\\\\'\'2025-09-30\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'5\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Graphic Designer\\\\\'\',\\\\\'\'Membuat desain visual untuk kebutuhan promosi.\\\\\'\',\\\\\'\'S1 Desain Komunikasi Visual\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'7500000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-03\\\\\'\',\\\\\'\'2025-10-03\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'6\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Backend Developer\\\\\'\',\\\\\'\'Mengembangkan API dan mengelola database.\\\\\'\',\\\\\'\'S1 Ilmu Komputer, pengalaman Node.js\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'11000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-07\\\\\'\',\\\\\'\'2025-10-07\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'7\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'HRD Officer\\\\\'\',\\\\\'\'Mengelola administrasi kepegawaian.\\\\\'\',\\\\\'\'S1 Psikologi atau Manajemen SDM\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'8500000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-12\\\\\'\',\\\\\'\'2025-10-12\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'8\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Sales Executive\\\\\'\',\\\\\'\'Menjual produk ke klien potensial dan menjaga hubungan dengan pelanggan.\\\\\'\',\\\\\'\'Pengalaman di bidang sales\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'7000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-08\\\\\'\',\\\\\'\'2025-10-08\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'9\\\\\'\',\\\\\'\'6\\\\\'\',\\\\\'\'UI/UX Designer\\\\\'\',\\\\\'\'Mendesain antarmuka pengguna yang intuitif dan user-friendly.\\\\\'\',\\\\\'\'S1 DKV atau setara, pengalaman Figma\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'9000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-15\\\\\'\',\\\\\'\'2025-10-15\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'10\\\\\'\',\\\\\'\'6\\\\\'\',\\\\\'\'Content Writer\\\\\'\',\\\\