ripsi` text NOT NULL,\\\\n  `persyaratan` varchar(255) NOT NULL,\\\\n  `mata_uang` varchar(255) NOT NULL,\\\\n  `gaji` varchar(255) NOT NULL,\\\\n  `kpn_gaji_diberi` varchar(11) NOT NULL,\\\\n  `tanggal_dibuka` date NOT NULL,\\\\n  `tanggal_ditutup` date NOT NULL,\\\\n  PRIMARY KEY (`id_lowongan`),\\\\n  KEY `id_perusahaan` (`id_perusahaan`)\\\\n) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\\\n\\\\n--\\\\n-- Dumping data untuk tabel `lowongan`\\\\n--\\\\n\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'1\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Software Engineer\\\\\'\',\\\\\'\'Mengembangkan dan memelihara aplikasi berbasis web.\\\\\'\',\\\\\'\'S1 Teknik Informatika, pengalaman 2 tahun\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'10000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-01\\\\\'\',\\\\\'\'2025-10-01\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'2\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Digital Marketing Specialist\\\\\'\',\\\\\'\'Bertanggung jawab atas strategi pemasaran digital.\\\\\'\',\\\\\'\'S1 Komunikasi, pengalaman 1 tahun\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'8000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-05\\\\\'\',\\\\\'\'2025-10-05\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'3\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Data Analyst\\\\\'\',\\\\\'\'Menganalisis data untuk mendukung pengambilan keputusan bisnis.\\\\\'\',\\\\\'\'S1 Statistika, menguasai SQL dan Python\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'9500000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-10\\\\\'\',\\\\\'\'2025-10-10\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'4\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Customer Service\\\\\'\',\\\\\'\'Menangani pertanyaan dan keluhan pelanggan.\\\\\'\',\\\\\'\'Minimal SMA, komunikatif\\\\\'\',\\\\\'\'IDR\\\\\'\',\\\\\'\'5000000\\\\\'\',\\\\\'\'Bulanan\\\\\'\',\\\\\'\'2025-09-01\\\\\'\',\\\\\'\'2025-09-30\\\\\'\');\\\\nINSERT INTO `lowongan` VALUES(\\\\\'\'5\\\\\'\',\\\\\'\'2\\\\\'\',\\\\\'\'Graphic Designer\\\\\'\